/**
 * Transforms Terraform state to match translated infrastructure.
 *
 * Pipeline: normalizeState -> buildAddressMap -> classifyByMappingType
 *           -> generateCommands -> generateRollback -> StateTransformPlan.
 *
 * @module state/state-transformer
 * @generated by code-generator (TASK-DATA-005)
 */

import type {
  ManifestEntry,
  StateData,
  StateDataV3,
  StateDataV4,
  TranslationManifest,
} from '@tla/shared';
import { generateRollback } from './rollback-generator.js';
import type { RollbackManifest } from './rollback-generator.js';
import { shellQuote } from './shell-quote.js';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/**
 * A terraform state mv command.
 */
export interface StateMoveCommand {
  readonly source: string;
  readonly destination: string;
  readonly commandString: string;
}

/**
 * A terraform import command.
 */
export interface StateImportCommand {
  readonly address: string;
  readonly resourceType: string;
  readonly manualTask: boolean;
  readonly commandString: string;
}

/**
 * A terraform state rm command.
 */
export interface StateRemoveCommand {
  readonly address: string;
  readonly reason: string;
  readonly commandString: string;
}

/**
 * The full state transformation plan.
 */
export interface StateTransformPlan {
  readonly moves: readonly StateMoveCommand[];
  readonly imports: readonly StateImportCommand[];
  readonly removes: readonly StateRemoveCommand[];
  readonly warnings: readonly string[];
  readonly rollbackManifest: RollbackManifest;
}

/**
 * A normalized state resource with its full address.
 */
interface NormalizedResource {
  readonly address: string;
  readonly type: string;
  readonly name: string;
  readonly mode: string;
}

/**
 * Map of source address -> manifest entry for correlation.
 */
interface AddressMapEntry {
  readonly stateAddress: string;
  readonly manifestEntry: ManifestEntry;
}

// ---------------------------------------------------------------------------
// Normalization
// ---------------------------------------------------------------------------

/**
 * Normalizes V3 state into a flat resource list.
 *
 * V3 format: modules[].resources is a Record<string, ...> where the key
 * IS the resource address. Module path ["root"] means no prefix; otherwise
 * prefix with module.<path[1]>.module.<path[2]>... etc.
 */
export function normalizeV3(state: StateDataV3): NormalizedResource[] {
  const results: NormalizedResource[] = [];

  for (const mod of state.modules) {
    // Build module prefix from path
    // ["root"] -> no prefix, ["root", "vpc"] -> "module.vpc."
    let prefix = '';
    if (mod.path.length > 1) {
      prefix = mod.path
        .slice(1)
        .map((p) => `module.${p}`)
        .join('.') + '.';
    }

    for (const [key, resource] of Object.entries(mod.resources)) {
      const address = `${prefix}${key}`;
      results.push({
        address,
        type: resource.type,
        name: key.includes('.') ? key.split('.').slice(1).join('.') : key,
        mode: 'managed',
      });
    }
  }

  return results.sort((a, b) => a.address.localeCompare(b.address));
}

/**
 * Normalizes V4 state into a flat resource list.
 *
 * V4 format: resources[] with type, name, module fields.
 * Address = [module.<mod>.]<type>.<name>
 * Data sources (mode === 'data') are skipped.
 */
export function normalizeV4(state: StateDataV4): NormalizedResource[] {
  const results: NormalizedResource[] = [];

  for (const resource of state.resources) {
    // Skip data sources — they are read-only lookups, not managed state
    if (resource.mode === 'data') {
      continue;
    }

    const prefix = resource.module ? `${resource.module}.` : '';
    const address = `${prefix}${resource.type}.${resource.name}`;

    results.push({
      address,
      type: resource.type,
      name: resource.name,
      mode: resource.mode,
    });
  }

  return results.sort((a, b) => a.address.localeCompare(b.address));
}

/**
 * Dispatches to V3 or V4 normalization based on state version.
 */
export function normalizeState(state: StateData): NormalizedResource[] {
  if (state.version === 3) {
    return normalizeV3(state as StateDataV3);
  }
  return normalizeV4(state as StateDataV4);
}

// ---------------------------------------------------------------------------
// Address correlation
// ---------------------------------------------------------------------------

/**
 * Builds a map correlating state addresses to manifest entries.
 *
 * ManifestEntry.sourceId is in "type.name" format (from dependency-graph).
 * We match state resources by constructing the same key from their type+name.
 */
export function buildAddressMap(
  resources: readonly NormalizedResource[],
  manifest: TranslationManifest,
): AddressMapEntry[] {
  // Index manifest entries by sourceId for O(1) lookup
  const manifestBySourceId = new Map<string, ManifestEntry>();
  for (const entry of manifest.entries) {
    manifestBySourceId.set(entry.sourceId, entry);
  }

  const results: AddressMapEntry[] = [];

  for (const res of resources) {
    // sourceId format is "type.name"
    const sourceId = `${res.type}.${res.name}`;
    const entry = manifestBySourceId.get(sourceId);
    if (entry) {
      results.push({
        stateAddress: res.address,
        manifestEntry: entry,
      });
    }
  }

  return results.sort((a, b) => a.stateAddress.localeCompare(b.stateAddress));
}

// ---------------------------------------------------------------------------
// Command generation
// ---------------------------------------------------------------------------

/**
 * Generates a terraform state mv command string.
 */
export function generateMoveCommand(
  source: string,
  destination: string,
): StateMoveCommand {
  return {
    source,
    destination,
    commandString: `terraform state mv ${shellQuote(source)} ${shellQuote(destination)}`,
  };
}

/**
 * Generates a terraform import command string.
 * Uses <RESOURCE_ID> placeholder since actual IDs come from the real state.
 */
export function generateImportCommand(
  address: string,
  resourceType: string,
): StateImportCommand {
  return {
    address,
    resourceType,
    manualTask: true,
    commandString: `terraform import ${shellQuote(address)} <RESOURCE_ID>`,
  };
}

/**
 * Generates a terraform state rm command string.
 */
export function generateRemoveCommand(
  address: string,
  reason: string,
): StateRemoveCommand {
  return {
    address,
    reason,
    commandString: `terraform state rm ${shellQuote(address)}`,
  };
}

// ---------------------------------------------------------------------------
// Classification dispatch
// ---------------------------------------------------------------------------

/**
 * Classifies address map entries by their manifest status and generates
 * the appropriate state commands.
 *
 * Dispatch table:
 * - translated / partial -> move (source -> target)
 * - expanded -> move (primary) + import (secondaries)
 * - advisory -> remove
 * - blocked -> skip with warning
 */
export function classifyByMappingType(
  entries: readonly AddressMapEntry[],
): {
  moves: StateMoveCommand[];
  imports: StateImportCommand[];
  removes: StateRemoveCommand[];
  warnings: string[];
} {
  const moves: StateMoveCommand[] = [];
  const imports: StateImportCommand[] = [];
  const removes: StateRemoveCommand[] = [];
  const warnings: string[] = [];

  for (const { stateAddress, manifestEntry } of entries) {
    const status = manifestEntry.status;
    const targets = manifestEntry.targetResources;

    switch (status) {
      case 'translated':
      case 'partial': {
        // Move to the first (and only) target resource
        if (targets.length > 0) {
          const target = targets[0]!;
          const destAddress = `${target.targetType}.${target.targetName}`;
          moves.push(generateMoveCommand(stateAddress, destAddress));
        }
        break;
      }

      case 'expanded': {
        // Compound expansion: primary gets move, secondaries get import
        // Primary: targetName matches sourceId.split('.')[1] (the name part)
        const sourceName = manifestEntry.sourceId.split('.')[1] ?? '';

        const primary = targets.find((t) => t.targetName === sourceName);
        const secondaries = targets.filter((t) => t.targetName !== sourceName);

        if (primary) {
          const destAddress = `${primary.targetType}.${primary.targetName}`;
          moves.push(generateMoveCommand(stateAddress, destAddress));
        }

        for (const sec of secondaries) {
          const secAddress = `${sec.targetType}.${sec.targetName}`;
          imports.push(generateImportCommand(secAddress, sec.targetType));
        }
        break;
      }

      case 'advisory': {
        removes.push(
          generateRemoveCommand(
            stateAddress,
            `Advisory resource: ${manifestEntry.sourceId}`,
          ),
        );
        break;
      }

      case 'blocked': {
        warnings.push(
          `SKIPPED: ${stateAddress} is blocked` +
            (manifestEntry.sourceId ? ` (source: ${manifestEntry.sourceId})` : ''),
        );
        break;
      }

      default: {
        // pending or unknown — skip with warning
        warnings.push(
          `SKIPPED: ${stateAddress} has unhandled status '${status}'.`,
        );
        break;
      }
    }
  }

  // Sort deterministically
  moves.sort((a, b) => a.source.localeCompare(b.source));
  imports.sort((a, b) => a.address.localeCompare(b.address));
  removes.sort((a, b) => a.address.localeCompare(b.address));
  warnings.sort((a, b) => a.localeCompare(b));

  return { moves, imports, removes, warnings };
}

// ---------------------------------------------------------------------------
// Orchestrator
// ---------------------------------------------------------------------------

/**
 * Transforms a Terraform state file to match the translated infrastructure.
 *
 * Pipeline:
 * 1. normalizeState   — flatten V3/V4 to uniform resource list
 * 2. buildAddressMap   — correlate state addresses with manifest entries
 * 3. classifyByMappingType — dispatch to move/import/remove/skip
 * 4. generateRollback  — produce inverse operations for undo
 * 5. Return StateTransformPlan
 *
 * @param state    - Parsed terraform state (V3 or V4).
 * @param manifest - Translation manifest from the compiler.
 * @param timestamp - Optional ISO timestamp for rollback manifest.
 * @returns The state transformation plan.
 */
export function transformState(
  state: StateData,
  manifest: TranslationManifest,
  timestamp?: string,
): StateTransformPlan {
  // 1. Normalize
  const resources = normalizeState(state);

  // 2. Correlate
  const addressMap = buildAddressMap(resources, manifest);

  // 3. Classify & generate commands
  const { moves, imports, removes, warnings } =
    classifyByMappingType(addressMap);

  // 4. Generate rollback
  const rollbackManifest = generateRollback(moves, imports, removes, timestamp);

  return {
    moves,
    imports,
    removes,
    warnings,
    rollbackManifest,
  };
}
